import{_ as t,o as n,c as o,a0 as a}from"./chunks/framework.Bmhw_dvp.js";const m=JSON.parse('{"title":"UI and Documentation Synchronization","description":"Rules for maintaining terminology alignment across the codebase, UI components, and documentation artifacts.","frontmatter":{"isInternal":true,"type":"Architecture Decision Record","title":"UI and Documentation Synchronization","description":"Rules for maintaining terminology alignment across the codebase, UI components, and documentation artifacts.","tags":["ui","documentation","conventions","naming"]},"headers":[],"relativePath":"adr/2026-07-06-ui-and-documentation-synchronization.md","filePath":"adr/2026-07-06-ui-and-documentation-synchronization.md"}'),i={name:"adr/2026-07-06-ui-and-documentation-synchronization.md"};function r(s,e,c,d,l,u){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="ui-and-documentation-synchronization" tabindex="-1">UI and Documentation Synchronization <a class="header-anchor" href="#ui-and-documentation-synchronization" aria-label="Permalink to &quot;UI and Documentation Synchronization&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>When updating UI terminology, Call-to-Action (CTA) labels, or Agent names (e.g., changing &quot;Director&quot; to &quot;Generate Visual Storyboard&quot;), there is a high risk of creating fragmentation if the changes are only made in the immediate file requested by the user.</p><p>Inconsistencies confuse the end-user and degrade the reliability of end-to-end testing, usage reporting, and product documentation.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Whenever an agent modifies a significant UI term, label, or concept name, they MUST proactively perform a global synchronization:</p><ol><li><strong>Component Alignment</strong>: Search for the old term across the <code>frontend/</code> directory (e.g., toolbars, empty states, modals, tab switchers) and update all related occurrences.</li><li><strong>E2E Test Alignment</strong>: Search the <code>frontend/e2e/</code> directory. Playwright tests often depend on specific text locators (e.g., <code>locator(&#39;button:has-text(&quot;Settings&quot;)&#39;)</code>). If a UI element is renamed, moved, or placed behind a dropdown menu, you MUST update the E2E tests to reflect the new DOM structure and text.</li><li><strong>Usage &amp; Analytics Alignment</strong>: Check how the term is represented in backend systems, usage tracking, or Audit Ledgers. If the backend system name cannot be changed (to preserve historical data), implement a display-time transformation on the frontend (e.g., mapping <code>entry.agentName === &#39;director&#39; ? &#39;storyboard&#39; : entry.agentName</code>).</li><li><strong>Documentation Alignment</strong>: Search all documentation artifacts (e.g., <code>product_documentation.md</code>, <code>e2e_use_cases.md</code>, <code>walkthrough.md</code>) for the old term and replace it with the new terminology.</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li><strong>Positive:</strong> Ensures a cohesive user experience, accurate product guides, and reliable automated tests.</li><li><strong>Negative:</strong> Requires slightly more token usage and processing time to run global searches and update secondary files.</li></ul><h2 id="ai-instruction" tabindex="-1">AI Instruction <a class="header-anchor" href="#ai-instruction" aria-label="Permalink to &quot;AI Instruction&quot;">​</a></h2><p>When a user asks to rename a feature, button, or agent:</p><ul><li>Do not stop at the primary file.</li><li>Use <code>grep_search</code> to find the old term in <code>frontend/src/</code> and the documentation directory.</li><li>Update all occurrences to maintain strict synchronization.</li></ul>',12)])])}const g=t(i,[["render",r]]);export{m as __pageData,g as default};
